export type LessonTeachingContent = {
  title: string;
  theory: string;
  watchFor: string;
  worked: { title: string; question: string; steps: string[]; answer: string };
  application: { title: string; explanation: string };
  check: { question: string; answer: string };
};

export const lessonTeachingContent: Record<string, LessonTeachingContent> = {
  "satellite-orbit": { title:"Why orbit is continuous free fall", theory:"Gravity supplies the inward centripetal acceleration. A circular orbit occurs when GM/r² equals v²/r; escape requires enough kinetic energy for total mechanical energy to reach zero.", watchFor:"Increase altitude and compare the weaker gravity arrow with the lower circular speed.", worked:{title:"400 km Earth orbit",question:"Estimate circular speed at r = 6.771×10⁶ m using GM = 3.986×10¹⁴ m³/s².",steps:["v = √(GM/r)","v = √(3.986×10¹⁴ / 6.771×10⁶)"],answer:"v ≈ 7.67 km/s; escape speed there is √2v ≈ 10.85 km/s."},application:{title:"Low-Earth observation satellites",explanation:"ISS-class spacecraft move sideways fast enough that Earth curves away beneath them while gravity continually bends the path."},check:{question:"Does a heavier satellite need a larger circular speed at the same altitude?",answer:"No. Satellite mass cancels from the gravity–centripetal equation."}},
  "universal-gravitation": { title:"Every mass creates an inverse-square field", theory:"Two masses attract with F = Gm₁m₂/r². The forces are equal and opposite, while field strength at a point depends on the source mass and distance.", watchFor:"Double the separation and see the force arrow shrink to one quarter.", worked:{title:"Two laboratory masses",question:"Find the attraction between 1000 kg and 500 kg separated by 2 m.",steps:["F = Gm₁m₂/r²","F = 6.674×10⁻¹¹×1000×500/2²"],answer:"F ≈ 8.34×10⁻⁶ N."},application:{title:"Tidal forces",explanation:"The Moon pulls more strongly on Earth’s near side than its far side because gravitational field strength changes with distance."},check:{question:"What happens to force if both masses double?",answer:"It becomes four times larger if separation is unchanged."}},
  "ac-generator": { title:"Rotating flux produces alternating emf", theory:"A coil rotating in a magnetic field has flux Φ = NBA cosθ. Faraday’s law gives ε = −dΦ/dt = NBAω sinθ, so emf reverses every half-turn.", watchFor:"Compare maximum flux with zero emf, then quarter-turn flux with peak emf.", worked:{title:"Peak generator voltage",question:"A 200-turn, 0.010 m² coil rotates at 50 rad/s in 0.20 T.",steps:["εmax = NBAω","εmax = 200×0.20×0.010×50"],answer:"εmax = 20 V."},application:{title:"Power-station alternator",explanation:"Steam or water turbines rotate coils or magnetic poles, producing the sinusoidal voltage supplied to the grid."},check:{question:"Why is emf zero when the coil’s flux is maximum?",answer:"Flux is momentarily not changing, so dΦ/dt = 0."}},
  "ac-lcr-resonance": { title:"Inductive and capacitive reactance can cancel", theory:"In a series LCR circuit, XL = 2πfL rises with frequency while XC = 1/(2πfC) falls. At resonance XL = XC, impedance is R and current is maximum.", watchFor:"Sweep through f₀ and observe the phase cross zero as current peaks.", worked:{title:"Resonant frequency",question:"Find f₀ for L = 0.20 H and C = 20 μF.",steps:["f₀ = 1/(2π√LC)","LC = 0.20×20×10⁻⁶"],answer:"f₀ ≈ 79.6 Hz."},application:{title:"Radio tuning",explanation:"A receiver selects one station by tuning an LC circuit to resonate at that carrier frequency."},check:{question:"Below resonance, is a series LCR circuit mainly capacitive or inductive?",answer:"Capacitive, because XC > XL."}},
  "capacitor-lab": { title:"Geometry stores separated charge and energy", theory:"For parallel plates C = εA/d. Connected capacitors share voltage in parallel and charge in series; stored energy is U = ½CV².", watchFor:"Reduce plate spacing and watch capacitance and stored charge increase at fixed voltage.", worked:{title:"Stored energy",question:"A 100 μF capacitor is charged to 12 V.",steps:["U = ½CV²","U = 0.5×100×10⁻⁶×12²"],answer:"U = 7.2 mJ."},application:{title:"Camera flash",explanation:"A capacitor charges slowly from a battery and releases its stored electrical energy rapidly through the flash tube."},check:{question:"What happens to energy if voltage doubles at fixed capacitance?",answer:"Energy becomes four times larger."}},
  "internal-resistance-cell": { title:"A real cell loses voltage inside itself", theory:"A cell with emf E and internal resistance r supplies I = E/(R+r). Its terminal voltage under load is V = E−Ir, so the V–I graph has intercept E and slope −r.", watchFor:"Close the key and increase load current; terminal voltage should sag.", worked:{title:"Loaded battery",question:"A 1.5 V cell with r = 0.20 Ω drives R = 2.8 Ω.",steps:["I = E/(R+r) = 1.5/3.0","Vterminal = E−Ir"],answer:"I = 0.50 A and Vterminal = 1.40 V."},application:{title:"Car-battery voltage sag",explanation:"The starter draws a large current, so internal resistance causes the measured battery voltage to fall temporarily."},check:{question:"What is terminal voltage with the circuit open?",answer:"Approximately the emf E because I = 0."}},
  "chemical-effects-current": { title:"Charge transfer drives chemical change", theory:"Current transports charge Q = It. Faraday’s law links deposited mass to charge: m = MIt/(zF), where z is electrons per ion.", watchFor:"Reverse polarity and observe which electrode gains material and which loses it.", worked:{title:"Copper plating",question:"Find copper deposited by 2.0 A for 30 min, with M = 63.55 g/mol and z = 2.",steps:["Q = 2.0×1800 = 3600 C","m = 63.55×3600/(2×96485) g"],answer:"m ≈ 1.19 g of copper."},application:{title:"Electroplated taps",explanation:"A thin chromium or nickel layer improves appearance and corrosion resistance while using little expensive metal."},check:{question:"If time doubles at constant current, what happens to deposited mass?",answer:"It doubles."}},
  "electric-power": { title:"Electrical energy is transferred at a measurable rate", theory:"Power is P = VI and, for a resistor, also I²R or V²/R. Energy billed by utilities is power multiplied by operating time.", watchFor:"Raise voltage and observe current, power, heating, and fuse margin change together.", worked:{title:"Kettle energy cost",question:"A 2.0 kW kettle runs for 6 min at ₹8 per kWh.",steps:["t = 6/60 = 0.10 h","E = Pt = 2.0×0.10 = 0.20 kWh"],answer:"Cost = 0.20×₹8 = ₹1.60."},application:{title:"Household circuit loading",explanation:"Several high-power appliances on one circuit may make total current exceed the fuse or breaker rating."},check:{question:"At fixed resistance, how does power change when voltage doubles?",answer:"P = V²/R, so power quadruples."}},
  "electrostatic-field-potential": { title:"Field is a vector; potential is a scalar", theory:"Electric fields from charges add vectorially, E = Σkq r̂/r², while potentials add algebraically, V = Σkq/r. A point can have V = 0 but E ≠ 0.", watchFor:"Move the probe onto a dipole’s perpendicular bisector and compare the zero potential with nonzero field.", worked:{title:"Potential near a point charge",question:"Find V at 0.30 m from +2.0 μC.",steps:["V = kq/r","V = 8.99×10⁹×2.0×10⁻⁶/0.30"],answer:"V ≈ +59.9 kV."},application:{title:"Lightning field buildup",explanation:"Charge separation in clouds creates large potential differences and fields that can exceed air’s breakdown strength."},check:{question:"Can two equal positive charges produce zero field midway?",answer:"Yes, their fields cancel there, but their potentials add to a positive value."}},
  "emi-faraday": { title:"Only changing magnetic flux induces emf", theory:"Faraday’s law is ε = −N dΦ/dt. The minus sign is Lenz’s law: induced current creates a magnetic effect opposing the flux change.", watchFor:"Stop the magnet: even with strong flux, the emf and current return to zero.", worked:{title:"Coil flux change",question:"A 100-turn coil’s flux per turn falls from 4 mWb to 1 mWb in 0.020 s.",steps:["|ε| = N|ΔΦ|/Δt","|ε| = 100×3×10⁻³/0.020"],answer:"|ε| = 15 V; polarity opposes the decrease."},application:{title:"Bicycle dynamo",explanation:"Wheel motion changes magnetic flux through a coil, inducing voltage for the lamp."},check:{question:"Does a stationary magnet inside a stationary coil induce steady current?",answer:"No, because flux is not changing."}},
  "heating-effect-current": { title:"Current converts electrical energy into thermal energy", theory:"Collisions of charge carriers with the lattice produce Joule heating H = I²Rt. Temperature rise depends on net heat after losses and on mc.", watchFor:"Double current and compare the much faster temperature rise caused by the square law.", worked:{title:"Heating coil",question:"A 5 Ω coil carries 3 A for 40 s.",steps:["H = I²Rt","H = 3²×5×40"],answer:"H = 1800 J."},application:{title:"Electric iron",explanation:"A high-resistance alloy element converts electrical energy to heat while tolerating high temperature."},check:{question:"If current halves, what fraction of the heating rate remains?",answer:"One quarter."}},
  "kirchhoff-circuit": { title:"Charge and energy are conserved at every junction and loop", theory:"Kirchhoff’s current law requires ΣIin = ΣIout. Kirchhoff’s voltage law requires the signed rises and drops around any closed loop to sum to zero.", watchFor:"Adjust the bridge resistor and watch node currents redistribute while KCL and both KVL residuals stay near zero.", worked:{title:"Junction current",question:"Currents 2.4 A and 0.7 A enter a junction; 1.1 A leaves through one branch.",steps:["ΣIin = ΣIout","2.4+0.7 = 1.1+I"],answer:"The remaining outgoing current is 2.0 A."},application:{title:"Automotive wiring",explanation:"Branch currents from lights, fans, and electronics must add to the current supplied through the main fuse."},check:{question:"Why must voltage drops equal source rises around a loop?",answer:"A charge returning to its starting point has no net energy change."}},
  "meter-bridge": { title:"A null method compares resistance ratios", theory:"At balance, no current flows through the galvanometer and X/R = l/(100−l). The result depends on a length ratio, reducing dependence on meter calibration.", watchFor:"Slide the jockey through the null point and observe galvanometer deflection reverse sign.", worked:{title:"Unknown resistance",question:"Balance occurs at l = 40 cm with R = 6 Ω.",steps:["X/R = l/(100−l)","X = 6×40/60"],answer:"X = 4.0 Ω."},application:{title:"Precision resistance comparison",explanation:"Null bridges can detect very small imbalances because the detector only needs to identify zero, not measure a large current accurately."},check:{question:"What happens to galvanometer direction on opposite sides of balance?",answer:"It reverses because the bridge potential difference changes sign."}},
  "ohms-law": { title:"Ohmic conductors have a constant V/I ratio", theory:"For an ohmic resistor at constant temperature, V = IR and a V-versus-I graph is a straight line through the origin with slope R. Heating can make resistance change.", watchFor:"Compare the resistor’s straight trace with the filament’s curved trace as temperature rises.", worked:{title:"Resistor current",question:"A 12 V supply is connected across 8 Ω.",steps:["I = V/R","I = 12/8"],answer:"I = 1.5 A."},application:{title:"LED current limiting",explanation:"A series resistor is chosen so the remaining supply voltage produces a safe current through an LED."},check:{question:"What are the units of the slope of a V–I graph?",answer:"Volts per ampere, which is ohms."}},
  "series-parallel-resistance": { title:"Topology determines equivalent resistance", theory:"Series components carry the same current and resistances add. Parallel branches share voltage and their conductances add: 1/Req = Σ1/R.", watchFor:"Rewire identical resistors and compare total current in series and parallel at the same supply voltage.", worked:{title:"Two parallel resistors",question:"Find Req for 6 Ω and 3 Ω in parallel.",steps:["1/Req = 1/6+1/3 = 3/6","Req = 1/(1/2)"],answer:"Req = 2 Ω."},application:{title:"Home wiring",explanation:"Appliances are connected in parallel so each receives full mains voltage and can switch independently."},check:{question:"Can a parallel equivalent resistance exceed its smallest branch resistance?",answer:"No; adding a branch provides another current path."}},
  "static-electricity": { title:"Electrons transfer, but total charge is conserved", theory:"Rubbing moves electrons between materials; it does not create charge. Charged bodies interact through Coulomb’s inverse-square force, and sharp fields can ionize air.", watchFor:"Rub the materials, separate them, then bring the charged object near a conductor to see induction before contact.", worked:{title:"Coulomb force",question:"Two 2 μC charges are 0.20 m apart.",steps:["F = k|q₁q₂|/r²","F = 8.99×10⁹×4×10⁻¹²/0.20²"],answer:"F ≈ 0.899 N, repulsive for like signs."},application:{title:"Lightning conductor",explanation:"A grounded conductor provides a controlled low-resistance path for charge during a strike and reduces dangerous potential differences."},check:{question:"Why can a neutral conductor be attracted to a charged rod?",answer:"Induction shifts opposite charge closer, producing a stronger near-side attraction."}},
  "transformer-lab": { title:"Changing core flux links two coils", theory:"An AC primary creates alternating magnetic flux. Ideally Vs/Vp = Ns/Np and Is/Ip = Np/Ns; frequency is unchanged, while real cores and wires dissipate power.", watchFor:"Drag secondary turns and observe voltage change while waveform frequency remains locked to the primary.", worked:{title:"Step-down transformer",question:"A 230 V primary has 920 turns; the secondary has 48 turns.",steps:["Vs/Vp = Ns/Np","Vs = 230×48/920"],answer:"Vs = 12.0 V ideally."},application:{title:"Phone charger",explanation:"A transformer stage lowers and isolates mains voltage before rectification and electronic regulation."},check:{question:"Does a transformer operate with steady DC?",answer:"Not continuously; steady DC produces no changing flux after switch-on."}},
  "logic-gates": { title:"Boolean rules turn voltage states into decisions", theory:"Logic gates map binary inputs to an output. Combinations of NAND gates are universal because NOT, AND, OR, and more complex functions can all be constructed from NAND.", watchFor:"Toggle each input and verify every truth-table row, including propagation delay at transitions.", worked:{title:"XOR decision",question:"What is A XOR B for input pairs 00, 01, 10, 11?",steps:["XOR is true when inputs differ","Evaluate each pair"],answer:"Outputs are 0, 1, 1, 0."},application:{title:"Half-adder sum bit",explanation:"A half-adder uses XOR for the sum bit and AND for the carry bit when adding two binary digits."},check:{question:"What does a floating or unknown input mean?",answer:"Its logic level is not guaranteed, so the output may also be unknown."}},
  "semiconductor-diode": { title:"A junction conducts asymmetrically", theory:"Forward bias lowers the depletion barrier and current rises rapidly; reverse bias widens the barrier and leaves only small leakage until breakdown. Rectifiers exploit this directionality.", watchFor:"Reverse the bias and compare depletion width, carrier flow, and the sign of current.", worked:{title:"Half-wave rectifier timing",question:"A 50 Hz AC source feeds a single-diode rectifier.",steps:["One positive pulse passes per input cycle","Pulse repetition equals source frequency"],answer:"Output ripple repeats at 50 Hz; a full-wave bridge would give 100 Hz."},application:{title:"DC power supply",explanation:"A diode bridge converts both AC half-cycles to one polarity before a capacitor smooths the voltage."},check:{question:"Does increasing light intensity change a diode’s forward threshold in this basic model?",answer:"No; forward conduction is controlled mainly by junction material and temperature."}},
  "sources-of-energy": { title:"A reliable grid balances power every hour", theory:"Generation plus storage discharge must match demand plus charging and losses. Renewable output varies with weather and time, so reliability, emissions, cost, and storage must be compared together.", watchFor:"Advance through a day and observe solar vanish at night while storage or dispatchable sources cover demand.", worked:{title:"Battery round-trip loss",question:"A battery stores 100 kWh with 90% round-trip efficiency.",steps:["Useful returned energy = ηEin","Eout = 0.90×100"],answer:"Only 90 kWh returns; 10 kWh is lost."},application:{title:"Evening peak planning",explanation:"Solar output falls just as household demand rises, so grids use storage, hydro, flexible generation, or demand shifting."},check:{question:"Why is installed MW not the same as energy generated each day?",answer:"Output depends on capacity factor and operating time."}},
  "bernoulli-fluid-flow": { title:"Faster flow trades pressure for kinetic energy", theory:"Continuity requires A₁v₁ = A₂v₂ for steady incompressible flow. Along a streamline, P + ½ρv² + ρgh stays constant when viscosity and pumps are neglected.", watchFor:"Narrow the throat and compare its higher speed with its lower static pressure.", worked:{title:"Venturi speed",question:"Water flows at 2 m/s through 4 cm² into a 1 cm² throat.",steps:["A₁v₁ = A₂v₂","v₂ = (4/1)×2"],answer:"The throat speed is 8 m/s."},application:{title:"Aircraft pitot-static system",explanation:"The difference between stagnation and static pressure is used to infer airspeed."},check:{question:"At equal height, what happens to pressure where speed increases?",answer:"Static pressure decreases in the ideal Bernoulli model."}},
  "buoyancy": { title:"Displaced fluid produces an upward force", theory:"Archimedes’ principle gives Fb = ρfluid gVdisplaced. A floating object settles where buoyant force equals weight; a fully submerged denser body continues downward.", watchFor:"Lower the object and compare displaced volume, buoyant force, and apparent weight.", worked:{title:"Half-submerged block",question:"A 0.002 m³ block floats half submerged in water.",steps:["Vdisplaced = 0.001 m³","Fb = 1000×9.81×0.001"],answer:"Fb = 9.81 N, equal to the block’s weight at equilibrium."},application:{title:"Cargo ship loading",explanation:"Adding cargo increases weight, so the hull sinks farther and displaces more water until forces balance again."},check:{question:"Does buoyant force depend directly on an object’s mass?",answer:"No; it depends on displaced fluid volume and density, though mass affects how much must be displaced to float."}},
  "density-float-sink": { title:"Average density predicts floating behavior", theory:"Density is mass per volume. If object density is below fluid density it can float partially submerged; equal density gives neutral buoyancy, and greater density leads to sinking.", watchFor:"Move the same object between oil, water, and denser liquid layers.", worked:{title:"Submerged fraction",question:"A 750 kg/m³ wooden block floats in 1000 kg/m³ water.",steps:["Vsub/V = ρobject/ρfluid","Vsub/V = 750/1000"],answer:"75% of its volume is submerged."},application:{title:"Submarine ballast",explanation:"Taking water into ballast tanks raises average density to dive; expelling it lowers average density to rise."},check:{question:"Can a very massive object float?",answer:"Yes, if its total volume makes its average density lower than the fluid’s."}},
  "fluid-pressure": { title:"Hydrostatic pressure grows with vertical depth", theory:"In a stationary fluid, gauge pressure is ρgh. It depends on density and vertical depth, not container shape; pressure at a point acts in all directions.", watchFor:"Move probes to equal depth in differently shaped arms and compare readings.", worked:{title:"Pool pressure",question:"Find water gauge pressure 3.0 m below the surface.",steps:["Pgauge = ρgh","P = 1000×9.81×3.0"],answer:"P ≈ 29.4 kPa."},application:{title:"Dam wall thickness",explanation:"Deeper water exerts greater pressure, so dam walls are built thicker near the bottom."},check:{question:"Do two points at the same depth in connected water have different pressure because one side is wider?",answer:"No, their hydrostatic pressure is equal."}},
  "force-and-pressure": { title:"The same force can be concentrated or spread out", theory:"Pressure is normal force divided by contact area, P = F/A. Changing area does not change the applied force, but it changes how intensely the surface is loaded.", watchFor:"Keep force fixed and shrink the contact pad; pressure and deformation rise.", worked:{title:"Box on a floor",question:"A 600 N box rests on a 0.30 m² face.",steps:["P = F/A","P = 600/0.30"],answer:"P = 2000 Pa."},application:{title:"Snowshoes",explanation:"A large contact area lowers pressure on snow, reducing how far a person sinks."},check:{question:"Why does a sharp knife cut more easily?",answer:"Its small edge area produces larger pressure for the same force."}},
  "electromagnet": { title:"Electric current organizes a magnetic field", theory:"An ideal solenoid has B ≈ μNI/L. More turns, current, or core permeability strengthen the field; reversing current reverses north and south poles.", watchFor:"Reverse current and observe field arrows and pole labels swap without changing magnitude.", worked:{title:"Air-core solenoid",question:"A 0.20 m coil has 500 turns carrying 1.5 A.",steps:["B = μ₀NI/L","B = 4π×10⁻⁷×500×1.5/0.20"],answer:"B ≈ 4.71 mT."},application:{title:"Scrapyard lifting magnet",explanation:"A current-controlled electromagnet lifts steel and releases it when current is switched off."},check:{question:"Why does an iron core strengthen the field?",answer:"Its magnetic domains align, giving much higher effective permeability than air."}},
  "lorentz-force": { title:"Fields steer moving charge", theory:"A charge experiences F = q(E + v×B). The magnetic part is perpendicular to velocity, so it changes direction but not speed in a uniform field.", watchFor:"Reverse charge sign and see the trajectory curve to the opposite side.", worked:{title:"Electron path radius",question:"An electron at 2.0×10⁶ m/s enters 0.010 T perpendicular to B.",steps:["r = mv/(|q|B)","r = 9.11×10⁻³¹×2.0×10⁶/(1.602×10⁻¹⁹×0.010)"],answer:"r ≈ 1.14 mm."},application:{title:"Mass spectrometer",explanation:"Ions with different mass-to-charge ratios follow different radii and can be separated."},check:{question:"What magnetic force acts when velocity is parallel to B?",answer:"Zero, because v×B = 0."}},
  "magnetic-field-current": { title:"A current-carrying wire creates circular field lines", theory:"For a long straight wire, B = μ₀I/(2πr). The right-hand rule gives direction, while magnitude rises with current and falls with distance.", watchFor:"Move the probe outward and observe the 1/r decrease; reverse current to flip direction.", worked:{title:"Field near a wire",question:"Find B 5 cm from a 10 A long wire.",steps:["B = μ₀I/(2πr)","B = 4π×10⁻⁷×10/(2π×0.05)"],answer:"B = 40 μT."},application:{title:"Clamp current sensor",explanation:"A magnetic sensor around a conductor estimates current without breaking the circuit."},check:{question:"If distance doubles, what happens to B?",answer:"It halves for an ideal long straight wire."}},
  "computational-physics-workflow": { title:"A numerical answer needs convergence evidence", theory:"A simulation approximates continuous physics with finite steps. Stability, truncation error, model assumptions, and reproducible settings determine whether a computed result is trustworthy.", watchFor:"Halve the time step and compare error reduction and computational cost.", worked:{title:"Convergence ratio",question:"Errors are 0.040 at Δt = 0.1 s and 0.010 at Δt = 0.05 s.",steps:["Error fell by 0.040/0.010 = 4","Step size fell by 2"],answer:"The observed behavior is consistent with a second-order method."},application:{title:"Weather-model grid refinement",explanation:"Forecasters compare multiple resolutions to distinguish robust features from numerical artifacts."},check:{question:"Why is a smaller step not automatically better?",answer:"It costs more and may still be unstable or dominated by model/input error."}},
  "measurement-errors": { title:"Measurements need correction and uncertainty", theory:"Systematic errors shift readings predictably; random errors create scatter. Corrections are applied before averaging, and significant figures should reflect measurement uncertainty.", watchFor:"Adjust zero error and see every corrected reading shift before the mean is rounded.", worked:{title:"Vernier zero correction",question:"A caliper reads 12.36 mm with +0.04 mm zero error.",steps:["Corrected = observed − zero error","12.36−0.04"],answer:"Corrected length = 12.32 mm."},application:{title:"Machining tolerance",explanation:"A shaft dimension is useful only when its uncertainty is small enough to decide whether it fits the allowed tolerance."},check:{question:"Does repeating measurements remove a fixed zero error?",answer:"No. Repetition reduces random uncertainty, not systematic bias."}},
  "balanced-unbalanced-forces": { title:"Net force changes velocity, not necessarily position", theory:"Forces add as vectors. If ΣF = 0, acceleration is zero and an object may remain at rest or move at constant velocity; nonzero net force produces a = ΣF/m.", watchFor:"Make pulls equal while the cart is already moving and observe constant velocity rather than forced stopping.", worked:{title:"Tug-of-war cart",question:"Right pull is 70 N, left pull is 50 N, and cart mass is 10 kg.",steps:["Fnet = 70−50 = 20 N right","a = Fnet/m = 20/10"],answer:"a = 2.0 m/s² to the right."},application:{title:"Cruising car",explanation:"At constant road speed, engine force balances drag and rolling resistance even though the car is moving."},check:{question:"Do balanced forces mean no motion?",answer:"No. They mean no change in velocity."}},
  "circular-motion": { title:"Circular motion requires inward acceleration", theory:"Velocity is tangent to the path while centripetal acceleration points toward the center. Its magnitude is v²/r = ω²r and the required inward force is mv²/r.", watchFor:"Release the mass and observe it continue along the instantaneous tangent.", worked:{title:"Car on a bend",question:"A 1000 kg car travels at 15 m/s around a 50 m radius curve.",steps:["ac = v²/r = 225/50","Fc = mac"],answer:"ac = 4.5 m/s² and Fc = 4500 N inward."},application:{title:"Banked road",explanation:"Road banking lets part of the normal force point inward, reducing reliance on tire friction."},check:{question:"Is centripetal force a new kind of force?",answer:"No. It is the net inward role supplied by tension, friction, gravity, normal force, or a combination."}},
  "conservation-of-energy": { title:"Energy changes form while the total ledger closes", theory:"Gravity converts potential energy mgh to kinetic energy ½mv². With friction, mechanical energy decreases but thermal energy increases by the same amount in the modeled closed system.", watchFor:"Compare total energy bars with and without friction as the cart descends.", worked:{title:"Frictionless drop",question:"A cart starts from rest 5.0 m above the bottom.",steps:["mgh = ½mv²; mass cancels","v = √(2gh) = √(2×9.81×5)"],answer:"v ≈ 9.90 m/s at the bottom."},application:{title:"Roller coaster",explanation:"The first hill stores gravitational energy that becomes speed; friction and air drag convert some to heat and sound."},check:{question:"Why does mass cancel from frictionless speed-from-height?",answer:"Both gravitational potential and kinetic energy are proportional to mass."}},
  "distance-time-graph": { title:"Graph slope tells how fast position changes", theory:"On a distance–time graph, slope Δd/Δt is speed. A horizontal segment means rest, and a steeper straight segment means faster uniform motion.", watchFor:"Build a stop–move–fast sequence and match each motion interval to its graph segment.", worked:{title:"Reading graph slope",question:"Distance rises from 20 m at 4 s to 50 m at 10 s.",steps:["v = Δd/Δt","v = (50−20)/(10−4)"],answer:"Average speed = 5.0 m/s."},application:{title:"Delivery tracking",explanation:"A flat section in a distance history shows a stop; changes in slope reveal different travel speeds."},check:{question:"Does a higher point on the graph always mean greater speed?",answer:"No. Speed is represented by slope, not graph height."}},
  "elastic-collision": { title:"Momentum is conserved; kinetic energy depends on elasticity", theory:"For an isolated one-dimensional collision, total momentum before and after is equal. A perfectly elastic collision also conserves kinetic energy; coefficient of restitution controls relative separation speed.", watchFor:"Use equal masses and one stationary cart to observe velocity exchange at e = 1.", worked:{title:"Equal-mass elastic collision",question:"A 1 kg cart at 3 m/s strikes an identical stationary cart elastically.",steps:["Momentum and kinetic energy are conserved","Equal masses exchange velocities"],answer:"Cart A stops and cart B moves at 3 m/s."},application:{title:"Newton’s cradle",explanation:"Nearly elastic impacts transmit momentum and energy through the middle balls to the ball at the far end."},check:{question:"Is momentum conserved in an inelastic isolated collision?",answer:"Yes, though kinetic energy is not."}},
  "free-fall": { title:"Ideal gravity gives every mass the same acceleration", theory:"Near Earth and without air resistance, vertical acceleration is constant at −g. Position and velocity follow y = y₀+v₀t−½gt² and v = v₀−gt.", watchFor:"Drop different masses from the same height and compare their identical motion.", worked:{title:"Drop from 20 m",question:"How long does an object dropped from rest take to fall 20 m?",steps:["h = ½gt²","t = √(2h/g) = √(40/9.81)"],answer:"t ≈ 2.02 s."},application:{title:"Drop-tower experiment",explanation:"Short periods of near-weightlessness occur when the apparatus and its contents accelerate downward together."},check:{question:"Why does a feather fall more slowly in air?",answer:"Air resistance is large compared with its weight; in vacuum it falls with the same g as other objects."}},
  "friction": { title:"Static friction adapts before kinetic sliding begins", theory:"Static friction matches the required opposing force up to μsN. After slipping begins, kinetic friction has magnitude approximately μkN and opposes relative motion.", watchFor:"Ramp the pull slowly and observe friction rise, peak, then drop at breakaway.", worked:{title:"Breakaway force",question:"A 5 kg block rests on a level surface with μs = 0.40.",steps:["N = mg = 5×9.81","fs,max = μsN"],answer:"fs,max ≈ 19.6 N."},application:{title:"Anti-lock braking",explanation:"Keeping tires rolling preserves controllable static friction instead of uncontrolled sliding friction."},check:{question:"Is static friction always μsN?",answer:"No. It takes any value needed up to that maximum."}},
  "hooke-s-law": { title:"A spring’s restoring force grows with extension", theory:"Within its elastic limit, F = −kx. At static equilibrium mg = kx; beyond the elastic region, proportionality may fail and permanent deformation may remain.", watchFor:"Add calibrated masses and use the force–extension graph slope to measure k.", worked:{title:"Spring extension",question:"A 0.20 kg mass hangs from a 40 N/m spring.",steps:["At equilibrium kx = mg","x = 0.20×9.81/40"],answer:"x ≈ 0.0491 m = 4.91 cm."},application:{title:"Spring scale",explanation:"A calibrated spring converts extension into a force reading as long as it remains elastic."},check:{question:"What does the slope of an F-versus-x graph equal?",answer:"The spring constant k in N/m."}},
  "inclined-plane": { title:"Gravity resolves into components along and normal to a slope", theory:"The downslope component is mg sinθ and the normal component is mg cosθ. Static friction can hold the block until the required force exceeds μsN.", watchFor:"Raise the angle through the angle of repose and identify the transition from held to sliding.", worked:{title:"Frictionless ramp",question:"Find acceleration down a 30° frictionless incline.",steps:["a = g sinθ","a = 9.81×sin30°"],answer:"a = 4.905 m/s²."},application:{title:"Loading ramp",explanation:"A longer, shallower ramp reduces the force needed to raise a load, trading force for distance."},check:{question:"At what angle does μs = 0.50 just fail to hold?",answer:"θcritical = arctan(0.50) ≈ 26.6°."}},
  "mass-and-weight": { title:"Mass is invariant; weight depends on local gravity", theory:"Mass measures inertia and does not change with location. Weight is gravitational force W = mg, while a scale measures apparent weight N, which also changes with elevator acceleration.", watchFor:"Move the same object from Earth to Moon and compare unchanged balance mass with smaller spring-scale reading.", worked:{title:"Moon weight",question:"Find the weight of a 60 kg person where g = 1.62 m/s².",steps:["W = mg","W = 60×1.62"],answer:"W = 97.2 N; mass remains 60 kg."},application:{title:"Elevator scale",explanation:"A scale reads above mg while accelerating upward and below mg while accelerating downward."},check:{question:"Why is scale reading zero in free fall?",answer:"The person and scale accelerate together, so no normal force is required."}},
  "newton-s-second-law": { title:"Acceleration follows net force and inertia", theory:"Newton’s second law is ΣF = ma. Acceleration points with net force, grows in direct proportion to force, and decreases as mass increases.", watchFor:"Hold force fixed, double mass, and compare the halved slope of the velocity graph.", worked:{title:"Crate acceleration",question:"A 12 kg crate is pushed with 50 N against 14 N friction.",steps:["Fnet = 50−14 = 36 N","a = Fnet/m = 36/12"],answer:"a = 3.0 m/s²."},application:{title:"Loaded shopping cart",explanation:"The same push produces less acceleration after the cart is filled because its inertia is larger."},check:{question:"Can velocity be rightward while acceleration is leftward?",answer:"Yes; the object then slows while still moving right."}},
  "projectile-motion": { title:"Horizontal and vertical motion evolve independently", theory:"Without drag, horizontal velocity is constant while vertical velocity changes by −g each second. Combining them produces a parabola.", watchFor:"Show component ghosts and compare uniform horizontal spacing with changing vertical spacing.", worked:{title:"Level-ground range",question:"A ball launches at 20 m/s and 45° with g = 9.81 m/s².",steps:["R = u²sin2θ/g","R = 400×sin90°/9.81"],answer:"R ≈ 40.8 m."},application:{title:"Basketball arc",explanation:"Players choose speed and angle so the ball’s two-dimensional trajectory intersects the hoop."},check:{question:"At the highest point, is acceleration zero?",answer:"No. Vertical velocity is zero momentarily, but acceleration remains downward at g."}},
  "rotational-dynamics": { title:"Torque changes angular motion", theory:"Torque τ = rFsinφ produces angular acceleration α = τ/I. Moving mass outward increases moment of inertia and makes the same torque less effective.", watchFor:"Drag radial masses outward while holding torque fixed and see α decrease.", worked:{title:"Flywheel acceleration",question:"A 6 N tangential force acts at 0.40 m on a wheel with I = 1.2 kg·m².",steps:["τ = rF = 0.40×6 = 2.4 N·m","α = τ/I"],answer:"α = 2.0 rad/s²."},application:{title:"Figure-skater spin",explanation:"Pulling arms inward reduces I, so angular speed rises when angular momentum is conserved."},check:{question:"Which force component produces torque?",answer:"The component perpendicular to the radius."}},
  "simple-pendulum": { title:"Gravity restores a displaced pendulum", theory:"The exact angular acceleration is −(g/L)sinθ. For small angles, sinθ ≈ θ and the period is T = 2π√(L/g), independent of bob mass.", watchFor:"Compare small and large release angles to see finite-angle period increase.", worked:{title:"One-metre pendulum",question:"Find the small-angle period for L = 1.00 m.",steps:["T = 2π√(L/g)","T = 2π√(1/9.81)"],answer:"T ≈ 2.01 s."},application:{title:"Pendulum clock",explanation:"A stable length gives a repeatable period, allowing oscillations to count time."},check:{question:"What happens to period if length becomes four times larger?",answer:"It doubles."}},
  "uniform-motion": { title:"Constant velocity makes position linear in time", theory:"Uniform motion has zero acceleration and x = x₀+vt. Equal time intervals produce equal displacements; negative velocity gives a downward x–t slope.", watchFor:"Turn on equal-time markers and verify that their spacing stays constant.", worked:{title:"Train position",question:"A train at x₀ = 30 m moves at −5 m/s for 8 s.",steps:["x = x₀+vt","x = 30+(−5)(8)"],answer:"x = −10 m."},application:{title:"Conveyor belt",explanation:"A belt at constant speed carries packages equal distances in equal times."},check:{question:"What is the slope of a velocity–time graph for uniform motion?",answer:"Zero, because acceleration is zero."}},
  "vector-resolution": { title:"Components are projections, not separate forces", theory:"A vector A at angle θ has Cartesian components Ax = Acosθ and Ay = Asinθ. Rotated axes use the angle relative to those axes, and components recombine to the original vector.", watchFor:"Rotate the axes without changing the physical vector and observe its component values change.", worked:{title:"Resolve a pull",question:"Resolve 100 N at 30° above horizontal.",steps:["Fx = 100cos30°","Fy = 100sin30°"],answer:"Fx = 86.6 N, Fy = 50.0 N."},application:{title:"Towing a sled",explanation:"The horizontal component accelerates the sled while the upward component reduces the normal force and friction."},check:{question:"Can a component be negative?",answer:"Yes, when the vector projects opposite the positive axis direction."}},
  "work-power": { title:"Work transfers energy; power measures its rate", theory:"Constant-force work is W = Fs cosθ. Net work equals change in kinetic energy, and average power is W/Δt.", watchFor:"Rotate the applied force toward 90° and see useful work fall even if force magnitude stays fixed.", worked:{title:"Angled pull",question:"A 40 N force pulls 5 m at 60° to displacement.",steps:["W = Fs cosθ","W = 40×5×cos60°"],answer:"W = 100 J."},application:{title:"Stair climbing",explanation:"Two people may do the same mgh work, but the faster climber develops more power."},check:{question:"Can work be negative?",answer:"Yes, when force has a component opposite displacement."}},
  "advanced-quantum-operators": { title:"Operators transform states and define observables", theory:"A normalized qubit |ψ⟩ = α|0⟩+β|1⟩ has probabilities |α|² and |β|². Unitary gates rotate the state; measurement projects it onto an eigenstate.", watchFor:"Apply a Hadamard gate to |0⟩ and compare the state vector with the 50–50 histogram.", worked:{title:"Born probabilities",question:"For α = √3/2 and β = 1/2, find Z-basis probabilities.",steps:["P(0)=|α|²=3/4","P(1)=|β|²=1/4"],answer:"P(0)=75%, P(1)=25%; they sum to 1."},application:{title:"Quantum bit control",explanation:"Gate sequences deliberately rotate qubit states before measurement in quantum algorithms."},check:{question:"Does one measurement reveal both amplitudes?",answer:"No. It returns one allowed outcome; repeated preparations estimate probabilities."}},
  "bohr-model": { title:"Atomic energies are quantized", theory:"Hydrogenic levels obey En = −13.6Z²/n² eV. A transition emits or absorbs a photon with positive energy |ΔE| = hf = hc/λ.", watchFor:"Drag the electron between allowed shells and match photon color to the level-energy gap.", worked:{title:"Hydrogen Hα line",question:"Find the energy for the n=3 to n=2 transition.",steps:["E3 = −13.6/9 = −1.51 eV","E2 = −13.6/4 = −3.40 eV; Ephoton = 1.89 eV"],answer:"λ ≈ 656 nm, the red Hα line."},application:{title:"Stellar spectroscopy",explanation:"Hydrogen absorption and emission lines reveal composition and physical conditions in stars."},check:{question:"Why are only particular wavelengths emitted?",answer:"Only discrete energy-level differences are allowed."}},
  "de-broglie-wavelength": { title:"Matter carries a wavelength set by momentum", theory:"A particle with momentum p has de Broglie wavelength λ = h/p. For a nonrelativistic electron accelerated through V, p = √(2meV).", watchFor:"Increase accelerating voltage and observe wavelength and diffraction-ring spacing shrink.", worked:{title:"Electron at 150 V",question:"Estimate its de Broglie wavelength.",steps:["λ = h/√(2meeV)","Insert h, me, e, and V = 150 V"],answer:"λ ≈ 0.100 nm."},application:{title:"Electron microscope",explanation:"Accelerated electrons have wavelengths far shorter than visible light, enabling finer spatial resolution."},check:{question:"If electron voltage quadruples, what happens to λ?",answer:"It halves in the nonrelativistic regime."}},
  "nuclear-decay": { title:"Each nucleus decays randomly; ensembles are predictable", theory:"A nucleus has no scheduled decay time, but a large population follows N = N₀2^(−t/T½). Activity A = λN decreases with the same exponential law.", watchFor:"Repeat with the same seed for reproducibility, then change seed while comparing the same smooth expectation curve.", worked:{title:"Two half-lives",question:"A sample begins with 8000 undecayed nuclei and T½ = 6 h.",steps:["After 6 h: 4000 remain","After 12 h: 2000 remain"],answer:"Expected count after 12 h is 2000."},application:{title:"Medical tracer",explanation:"A suitable half-life keeps a tracer active long enough to image while limiting prolonged radiation exposure."},check:{question:"Does exactly half of a small sample always decay in one half-life?",answer:"No. Half is the statistical expectation; small samples fluctuate."}},
  "photoelectric-equation": { title:"One photon transfers energy to one electron", theory:"Emission requires hf ≥ φ. The maximum electron kinetic energy is Kmax = hf−φ; intensity changes electron count, while frequency changes energy per photon.", watchFor:"Raise intensity below threshold and confirm that no electrons appear.", worked:{title:"Stopping potential",question:"Light gives Kmax = 1.8 eV. What reverse voltage stops the fastest electrons?",steps:["eVs = Kmax","An energy of 1.8 eV corresponds to 1.8 V per electron charge"],answer:"Stopping potential magnitude is 1.8 V."},application:{title:"Photocell",explanation:"Light ejects electrons from a photosurface, producing a current used in detectors and automatic controls."},check:{question:"Why does brighter sub-threshold light still fail?",answer:"Each photon individually lacks the work-function energy."}},
  "special-relativity-bridge": { title:"Spacetime measurements depend on relative motion", theory:"The Lorentz factor γ = 1/√(1−v²/c²) governs time dilation and longitudinal length contraction. All inertial observers still measure light speed c and agree on the spacetime interval.", watchFor:"Increase β and compare the stretched Earth-frame light-clock path with unchanged measured c.", worked:{title:"Clock at 0.8c",question:"One second elapses on the moving clock. How much Earth-frame time passes?",steps:["γ = 1/√(1−0.8²) = 1/0.6","Δt = γΔτ"],answer:"γ = 1.667, so Δt ≈ 1.67 s."},application:{title:"GPS clock correction",explanation:"Satellite navigation must account for relativistic clock-rate differences to maintain positioning accuracy."},check:{question:"Does the traveler feel their own clock running slowly?",answer:"No. Proper time is normal in the traveler’s own inertial frame."}},
  "glass-slab-refraction": { title:"A parallel slab shifts a ray without changing its final direction", theory:"Snell’s law n₁sin i = n₂sin r bends light at each surface. Parallel faces make the emergent ray parallel to the incident ray but laterally displaced.", watchFor:"Set normal incidence to make displacement zero, then increase angle and slab thickness.", worked:{title:"Air-to-glass angle",question:"A ray enters n = 1.50 glass from air at 30°.",steps:["sin r = sin30°/1.50 = 1/3","r = sin⁻¹(1/3)"],answer:"r ≈ 19.5°."},application:{title:"View through a window",explanation:"Oblique objects appear slightly shifted through a thick pane even though their outgoing rays remain parallel."},check:{question:"Which color bends more in ordinary glass, red or violet?",answer:"Violet, because its refractive index is usually larger."}},
  "human-eye-defects": { title:"Vision is sharp when the eye focuses on the retina", theory:"Myopia focuses distant light in front of the retina and needs negative lens power. Hyperopia focuses behind it and needs positive power; accommodation changes eye-lens power for near objects.", watchFor:"Select each defect and move the correcting lens until the focus marker lands on the retina.", worked:{title:"Myopic far point",question:"A myopic eye’s far point is 0.80 m. Find the lens power for distant vision.",steps:["A distant object must form a virtual image at −0.80 m","P = 1/f = 1/(−0.80)"],answer:"P = −1.25 D."},application:{title:"Prescription glasses",explanation:"Optometrists choose signed lens power to place the combined optical focus on the retina."},check:{question:"Which sign corrects hyperopia?",answer:"Positive converging power."}},
  "lens-formula": { title:"Thin lenses link object and image distances", theory:"Using Cartesian signs, 1/f = 1/v−1/u and magnification m = v/u. Convex lenses can form real or virtual images; concave lenses form virtual upright diminished images for real objects.", watchFor:"Drag a convex-lens object inside the focal point and watch the image become virtual and upright.", worked:{title:"Convex lens image",question:"For f = +20 cm and u = −60 cm, find v.",steps:["1/v = 1/f + 1/u","1/v = 1/20−1/60 = 1/30"],answer:"v = +30 cm; m = −0.5, so the image is inverted and half-size."},application:{title:"Camera focus",explanation:"Moving the lens relative to the sensor makes a real image land sharply on the sensor plane."},check:{question:"Can a virtual image be caught on a screen?",answer:"No, because the rays do not physically converge there."}},
  "optical-instruments": { title:"Two lenses multiply angular magnification", theory:"A compound microscope forms a magnified real intermediate image, then the eyepiece acts as a magnifier. A telescope’s objective forms an image of a distant object that the eyepiece enlarges angularly.", watchFor:"Switch instruments and follow the image orientation through objective and eyepiece stages.", worked:{title:"Astronomical telescope",question:"An objective has fo = 100 cm and eyepiece fe = 5 cm in normal adjustment.",steps:["Angular magnification M = −fo/fe","M = −100/5"],answer:"M = −20; magnitude 20× and the image is inverted."},application:{title:"Biological microscope",explanation:"Short focal lengths and carefully spaced lenses reveal structures too small for unaided angular resolution."},check:{question:"What is the normal-adjustment tube length of this telescope?",answer:"fo+fe = 105 cm."}},
  "mirror-formula": { title:"Curved mirrors form images by reflection", theory:"With New Cartesian signs, 1/f = 1/v+1/u and m = −v/u. A concave mirror can make real or virtual images; a convex mirror gives a virtual upright diminished image.", watchFor:"Move the object through the concave focal point and observe the image switch sides and orientation.", worked:{title:"Concave mirror",question:"For f = −20 cm and u = −60 cm, find v.",steps:["1/v = 1/f−1/u","1/v = −1/20+1/60 = −1/30"],answer:"v = −30 cm and m = −0.5: real, inverted, half-size."},application:{title:"Vehicle side mirror",explanation:"A convex mirror gives a wide field of view using upright diminished virtual images."},check:{question:"Where is a convex mirror’s focus?",answer:"Behind the mirror, so its focal length is positive under the stated Cartesian convention used by the lab."}},
  "multiple-reflection": { title:"Repeated reflections create a family of virtual images", theory:"Two mirrors at angle θ generate image count based on 360°/θ and object symmetry. Kaleidoscopes use repeated sectors to create rotational patterns.", watchFor:"Move the object off the bisector and inspect how boundary symmetry changes exact-integer cases.", worked:{title:"Mirrors at 60°",question:"How many images form for a centered object between two mirrors?",steps:["360°/60° = 6","For this even integer centered case, N = 6−1"],answer:"Five images form."},application:{title:"Kaleidoscope",explanation:"Three reflective strips repeatedly mirror colored pieces into a changing symmetric mosaic."},check:{question:"What generally happens as mirror angle decreases?",answer:"More reflected sectors and images fit around 360°."}},
  "prism-dispersion": { title:"Refractive index varies with wavelength", theory:"A prism refracts light at two nonparallel faces. Because n is usually larger for violet than red, violet suffers greater deviation and white light spreads into a spectrum.", watchFor:"Trace red and violet through both faces and compare their internal angles and final deviations.", worked:{title:"Minimum deviation index",question:"A 60° prism has minimum deviation 40°. Find n in air.",steps:["n = sin((A+δm)/2)/sin(A/2)","n = sin50°/sin30°"],answer:"n ≈ 1.532."},application:{title:"Spectrometer",explanation:"A prism separates wavelengths so emission lines can identify chemical elements."},check:{question:"Why does a parallel glass slab not spread colors as visibly as a prism?",answer:"Its second parallel face largely cancels angular separation, though small lateral color shifts can remain."}},
  "reflection-plane-mirror": { title:"A plane mirror preserves angle and apparent distance", theory:"The reflected direction follows r = d−2(d·n)n, giving incidence angle equal to reflection angle. The virtual image lies the same perpendicular distance behind the mirror as the object is in front.", watchFor:"Drag the candle and observer while checking ray extensions meet at the symmetric virtual image.", worked:{title:"Image location",question:"A candle is 35 cm in front of a plane mirror.",steps:["Plane-mirror image distance equals object distance","Image is behind the mirror"],answer:"The virtual image is 35 cm behind the mirror; candle-to-image separation is 70 cm."},application:{title:"Periscope",explanation:"Two plane mirrors redirect light while preserving the scene geometry seen by the observer."},check:{question:"Is the image laterally inverted because left and right swap in space?",answer:"More precisely, the coordinate perpendicular to the mirror reverses; the apparent left-right reversal follows from viewing geometry."}},
  "shadows-eclipses": { title:"Finite light sources create umbra and penumbra", theory:"Because the Sun has angular size, an occulting body can block all, part, or the central portion of its disk. Body order and apparent angular diameters distinguish solar, lunar, total, partial, and annular eclipses.", watchFor:"Move the Moon along its orbit and compare its apparent disk with the Sun at the observer pin.", worked:{title:"Angular diameter",question:"A Moon of diameter 3474 km is 384,400 km away.",steps:["Small-angle diameter α ≈ D/r","α ≈ 3474/384400 = 0.00904 rad"],answer:"α ≈ 0.518°, close to the Sun’s apparent size."},application:{title:"Solar-eclipse path",explanation:"Only observers crossed by the narrow umbral path see totality; nearby regions see a partial eclipse."},check:{question:"Why can an annular eclipse occur?",answer:"The Moon is farther away and appears slightly smaller than the Sun."}},
  "total-internal-reflection": { title:"Above the critical angle, transmission vanishes", theory:"When light travels from higher to lower refractive index, Snell’s law reaches a critical angle sinθc = n₂/n₁. At larger incidence angles no propagating refracted ray exists and reflection is total.", watchFor:"Sweep through θc and observe the transmitted ray approach the boundary before disappearing.", worked:{title:"Glass-to-air critical angle",question:"Find θc for n₁ = 1.50 and n₂ = 1.00.",steps:["sinθc = n₂/n₁ = 1/1.5","θc = sin⁻¹(0.6667)"],answer:"θc ≈ 41.8°."},application:{title:"Optical fibre",explanation:"A high-index core surrounded by lower-index cladding guides light through repeated total internal reflection."},check:{question:"Can total internal reflection occur from air into glass?",answer:"No; it requires travel from higher to lower refractive index."}},
  "chaotic-coupled-oscillators": { title:"Nonlinear coupling amplifies tiny initial differences", theory:"Coupled oscillators exchange energy through normal modes. At larger amplitudes nonlinear dynamics can make nearby initial states separate rapidly even though the equations are deterministic.", watchFor:"Launch two runs with almost identical angles and monitor their growing phase-space separation.", worked:{title:"Beat period",question:"Two normal modes have frequencies 1.00 Hz and 1.10 Hz.",steps:["Beat frequency = |f₂−f₁| = 0.10 Hz","Tbeat = 1/fbeat"],answer:"Energy-transfer envelope repeats every 10 s."},application:{title:"Bridge and building modes",explanation:"Coupled structural modes can exchange energy, so engineers avoid excitations near dangerous resonances."},check:{question:"Does chaotic mean random forces are acting?",answer:"No. Deterministic nonlinear systems can be chaotic."}},
  "calorimetry-mixing": { title:"Thermal equilibrium closes an energy balance", theory:"In an insulated calorimeter, heat lost by hotter parts equals heat gained by cooler parts: Σmc(Tf−Ti)=0, including the calorimeter heat capacity when relevant.", watchFor:"Pour samples together and track equal-and-opposite heat ledger entries approaching a common temperature.", worked:{title:"Equal water samples",question:"Mix equal masses of water at 80°C and 20°C with no losses.",steps:["Equal mc values give a weighted mean","Tf = (80+20)/2"],answer:"Tf = 50°C."},application:{title:"Food temperature control",explanation:"Mixing known amounts of hot and cold water can quickly reach a target preparation temperature."},check:{question:"Must final temperature lie between initial temperatures?",answer:"Yes for passive insulated mixing without phase change or internal heat generation."}},
  "gas-laws": { title:"Macroscopic pressure emerges from molecular collisions", theory:"An ideal gas obeys PV = nRT. At the particle level, higher Kelvin temperature means larger mean kinetic energy and faster wall collisions.", watchFor:"Compress isothermally and observe collision rate and pressure rise while molecular speed distribution stays tied to temperature.", worked:{title:"Boyle compression",question:"A gas at 100 kPa occupies 4.0 L and is compressed isothermally to 2.0 L.",steps:["P₁V₁ = P₂V₂","P₂ = 100×4/2"],answer:"P₂ = 200 kPa."},application:{title:"Bicycle pump",explanation:"Reducing trapped air volume raises pressure; rapid pumping also warms the gas because the process is not perfectly isothermal."},check:{question:"Why must Charles-law temperatures use kelvin?",answer:"Gas-law proportionality is referenced to absolute zero."}},
  "heat-and-temperature": { title:"Heat is energy transfer; temperature measures thermal state", theory:"Supplying Q changes temperature by ΔT = Q/(mc) when no phase change occurs. Equal energy inputs can cause different temperature rises because mass and specific heat differ.", watchFor:"Give equal heat to two materials and compare their thermometer slopes.", worked:{title:"Heating water",question:"How much energy heats 0.50 kg water by 10°C? Use c = 4186 J/kg·K.",steps:["Q = mcΔT","Q = 0.50×4186×10"],answer:"Q = 20.9 kJ."},application:{title:"Coastal climate",explanation:"Water’s large specific heat moderates daily temperature changes near oceans."},check:{question:"Is 40°C twice as hot as 20°C in an absolute-energy sense?",answer:"No; Celsius has an arbitrary zero. Absolute comparisons require kelvin and still depend on the system."}},
  "heat-transfer": { title:"Conduction, convection, and radiation use different mechanisms", theory:"Conduction follows material temperature gradients, convection transports energy with moving fluid, and radiation transfers electromagnetic energy with net rate proportional to T⁴−Tsur⁴.", watchFor:"Compare lattice vibration, circulating fluid, and radiation waves at the three stations.", worked:{title:"Wall conduction",question:"A 0.10 m² wall, 0.020 m thick, k = 0.5 W/m·K has ΔT = 20 K.",steps:["Q̇ = kAΔT/L","Q̇ = 0.5×0.10×20/0.020"],answer:"Heat-transfer rate = 50 W."},application:{title:"Vacuum flask",explanation:"Vacuum suppresses conduction and convection; reflective surfaces reduce radiation."},check:{question:"Why must Stefan–Boltzmann calculations use kelvin?",answer:"The fourth-power law is defined using absolute temperature."}},
  "statistical-ensemble-lab": { title:"Macroscopic laws emerge from distributions of microstates", theory:"An ensemble describes many allowed microscopic states under chosen constraints. Canonical energy probabilities follow Boltzmann weighting, while relative fluctuations generally shrink as system size grows.", watchFor:"Increase particle number and compare the narrowing relative-width of the energy histogram.", worked:{title:"Two-level Boltzmann ratio",question:"Levels differ by ΔE = kT. Find Pexcited/Pground.",steps:["Ratio = exp(−ΔE/kT)","Ratio = e⁻¹"],answer:"Pexcited/Pground ≈ 0.368."},application:{title:"Paramagnet temperature",explanation:"Populations of magnetic energy levels determine bulk magnetization and its temperature dependence."},check:{question:"Does an ensemble average describe the exact state of every particle?",answer:"No. It summarizes the distribution across possible microstates."}},
  "thermodynamic-process": { title:"Heat, work, and internal energy depend on the path", theory:"For the lab sign convention, ΔU = Q−W where W is work done by the gas. Isothermal, adiabatic, isobaric, and isochoric paths can connect states with different heat and work ledgers.", watchFor:"Compare two paths to the same final state: ΔU matches, but Q and W differ.", worked:{title:"Isobaric expansion",question:"Gas expands from 2 L to 5 L at 200 kPa.",steps:["W = PΔV","W = 200 kPa×3 L; 1 kPa·L = 1 J"],answer:"W = 600 J done by the gas."},application:{title:"Engine cycle",explanation:"A heat engine combines compression, heating, expansion, and cooling paths; enclosed P–V area is net work per cycle."},check:{question:"What boundary work occurs in an isochoric step?",answer:"Zero, because volume does not change."}},
  "chladni-plate": { title:"Resonance organizes a plate into nodes and antinodes", theory:"At a plate eigenfrequency, standing flexural waves form stationary nodal lines. Grains migrate away from strongly vibrating antinodes and collect near nodes.", watchFor:"Tune across resonance and watch the response peak while sand sharpens into a mode-specific pattern.", worked:{title:"Frequency scaling",question:"A similar mode’s frequency doubles when plate stiffness is changed. What happens to its period?",steps:["T = 1/f","Doubling f halves T"],answer:"The period becomes one half as large."},application:{title:"Instrument soundboard design",explanation:"Mode shapes influence how plates radiate sound, guiding the design of musical instruments and loudspeaker panels."},check:{question:"Do sand grains mark maximum displacement?",answer:"No. They collect along nodal lines of minimal vibration."}},
  "echo-speed-sound": { title:"An echo times a round trip", theory:"A pulse travels to a reflector and back, so distance d = vt/2. In dry air near room conditions, sound speed increases approximately 0.6 m/s per °C.", watchFor:"Move the wall marker and compare the outbound and reflected wavefront travel times.", worked:{title:"Cliff distance",question:"An echo returns after 0.80 s when v = 343 m/s.",steps:["Round-trip path = vt","d = vt/2 = 343×0.80/2"],answer:"The cliff is about 137 m away."},application:{title:"Ultrasonic rangefinder",explanation:"A sensor measures pulse return time to estimate distance to an object."},check:{question:"Why divide by two?",answer:"The measured time includes travel to the reflector and back."}},
  "em-spectrum": { title:"All electromagnetic waves share the same vacuum speed", theory:"In vacuum c = fλ, while photon energy E = hf. Frequency remains fixed when entering a medium, but speed and wavelength decrease by refractive index n.", watchFor:"Move continuously from radio to gamma and compare logarithmic wavelength and photon-energy scales.", worked:{title:"Green-light wavelength",question:"Find λ for f = 5.50×10¹⁴ Hz in vacuum.",steps:["λ = c/f","λ = 2.998×10⁸ / 5.50×10¹⁴"],answer:"λ ≈ 5.45×10⁻⁷ m = 545 nm."},application:{title:"Medical imaging bands",explanation:"Radio waves drive MRI signals, while higher-energy X-rays reveal internal structure through differential absorption."},check:{question:"Does light frequency change when it enters glass?",answer:"No; wavelength and speed change while boundary continuity preserves frequency."}},
  "sound-wave-anatomy": { title:"Sound is a traveling pressure and displacement pattern", theory:"In a longitudinal wave, particles oscillate parallel to propagation while compressions and rarefactions move through the medium. Wavelength follows λ = v/f.", watchFor:"Track one particle: it vibrates locally rather than traveling with the compression across the tube.", worked:{title:"Concert A wavelength",question:"Find wavelength of 440 Hz sound in 343 m/s air.",steps:["λ = v/f","λ = 343/440"],answer:"λ ≈ 0.780 m."},application:{title:"Speaker cone",explanation:"The cone alternately compresses and rarefies nearby air, launching a longitudinal pressure wave."},check:{question:"Does increasing amplitude change wavelength at fixed f and medium?",answer:"No in the linear model; it increases pressure variation and loudness."}},
  "polarization-lab": { title:"Polarizers select transverse field directions", theory:"An ideal polarizer transmits the component along its axis. For linearly polarized input, an analyzer gives I = I₀cos²θ; unpolarized light loses half its intensity at the first ideal polarizer.", watchFor:"Rotate crossed axes through 90° and follow the detector intensity to extinction.", worked:{title:"Analyzer at 60°",question:"Polarized light of intensity 80 W/m² meets an analyzer 60° away.",steps:["I = I₀cos²60°","I = 80×0.25"],answer:"I = 20 W/m²."},application:{title:"Glare-reducing sunglasses",explanation:"Polarizing lenses suppress strongly horizontally polarized reflections from roads and water."},check:{question:"Why can sound in air not be polarized?",answer:"It is longitudinal, not a transverse field wave."}},
  "single-slit-diffraction": { title:"Every part of a slit contributes to the far-field pattern", theory:"Interference across a slit of width a produces minima at a sinθ = mλ. The central maximum widens when wavelength or screen distance increases and narrows when slit width increases.", watchFor:"Close the slit and observe the broadening central maximum and wider intensity profile.", worked:{title:"First minimum",question:"Light λ = 600 nm passes a = 0.20 mm slit to a screen 2.0 m away.",steps:["For small angles y₁ ≈ Lλ/a","y₁ = 2×600×10⁻⁹/(0.20×10⁻³)"],answer:"y₁ ≈ 6.0 mm; central width ≈ 12 mm."},application:{title:"Camera aperture",explanation:"Very small apertures increase diffraction blur, limiting image sharpness despite improved geometric depth of field."},check:{question:"Does a narrower slit make a narrower diffraction pattern?",answer:"No. It makes the pattern wider."}},
  "sound-pitch-loudness": { title:"Frequency controls pitch; amplitude controls level", theory:"Period T = 1/f sets repetition rate and perceived pitch. Pressure amplitude sets intensity approximately through its square and changes sound-pressure level logarithmically.", watchFor:"Change frequency alone and compare waveform spacing while the modeled pressure level stays fixed.", worked:{title:"Pressure doubling",question:"Sound RMS pressure doubles with frequency unchanged.",steps:["Intensity ∝ p², so intensity becomes 4×","Level change = 10log₁₀4"],answer:"Sound level increases by about 6.0 dB."},application:{title:"Audio equalizer",explanation:"Frequency bands shape timbre, while gain changes their amplitudes and perceived loudness."},check:{question:"Does a louder pure tone necessarily have higher pitch?",answer:"No. Loudness and pitch are controlled mainly by different variables."}},
  "shm-spring": { title:"A linear restoring force produces sinusoidal motion", theory:"For F = −kx, angular frequency is ω₀ = √(k/m), period is 2π√(m/k), and acceleration always points toward equilibrium. Damping removes energy; periodic driving can create resonance.", watchFor:"Compare displacement, velocity, and acceleration at release, equilibrium crossing, and the opposite turning point.", worked:{title:"Oscillation period",question:"A 0.50 kg mass is attached to a 200 N/m spring.",steps:["T = 2π√(m/k)","T = 2π√(0.50/200)"],answer:"T ≈ 0.314 s."},application:{title:"Vehicle suspension",explanation:"Springs support the vehicle while dampers dissipate oscillation energy after a bump."},check:{question:"Where is speed maximum in undamped SHM?",answer:"At equilibrium, where spring potential energy is minimum."}},
  "wave-lab": { title:"Superposition builds interference and standing waves", theory:"Wave speed satisfies v = fλ. When waves overlap, displacements add algebraically; reflections can produce stationary nodes and antinodes when coherent waves travel oppositely.", watchFor:"Switch between fixed and free boundaries and observe whether the reflected displacement inverts.", worked:{title:"String wavelength",question:"A wave travels at 24 m/s with frequency 6 Hz.",steps:["λ = v/f","λ = 24/6"],answer:"λ = 4.0 m."},application:{title:"Guitar-string harmonics",explanation:"Reflections at fixed ends select standing-wave patterns whose allowed wavelengths determine musical frequencies."},check:{question:"At a standing-wave node, do waves disappear?",answer:"No. Opposite displacements cancel there at every instant."}},
  "young-double-slit": { title:"Coherent paths encode position as phase difference", theory:"Two narrow coherent slits produce bright fringes when path difference is mλ and dark fringes at (m+½)λ. For small angles, fringe spacing β = λD/d.", watchFor:"Drag the screen probe from a bright center to the first dark fringe and compare its phasors.", worked:{title:"Fringe spacing",question:"λ = 600 nm, screen distance D = 2.0 m, slit separation d = 0.50 mm.",steps:["β = λD/d","β = 600×10⁻⁹×2/(0.50×10⁻³)"],answer:"β = 2.4 mm."},application:{title:"Optical metrology",explanation:"Tiny displacement or refractive-index changes shift interference fringes and can be measured precisely."},check:{question:"What happens to spacing if slit separation doubles?",answer:"It halves."}},
};
